pageStyle:
	
.research-data-table > thead > tr > th,
.research-data-table > tbody > tr > td {
    width: calc(100% / 7);
}

.research-data-table > tbody > tr > td > span{
background-image: url("../images/green_block.png") !important;
}

.research-data-table > tbody > tr > td:nth-child(3) > span{
background-image: url("../images/red_block.png") !important;
}

td.topscore, td.curatedapproach, td.eip, td.icp {
padding: 0;
border: solid 1px #ffffff !important;
}

span.cell-weight-0 {
background-color: #dddddd;
color: #dddddd;
}

.feature-table th, .feature-table td {
width: calc(100% / 6);
}
